CODES_WIN = dict(space=0x20, **{'return':0x0D}, tab=0x09, backspace=0x08, escape=0x1B,
                 left=0x25, up=0x26, right=0x27, down=0x28)
CODES_XD = dict(space='space', **{'return':'Return'}, tab='Tab', backspace='BackSpace', escape='Escape',
                left='Left', right='Right', up='Up', down='Down')
SP = {'space','return','tab','backspace','escape','left','right','up','down'}
_bad = {'Cc','Cf','Cn','Co','Cs'}

def _typable(t): return 0 < len(t) <= 8 and not any(c.isspace() or unicodedata.category(c) in _bad for c in t)
def _typed(sym): return sym.split(',')[0].replace('…','').strip() or sym

def _glyphs():
    "Symbol set from glyph_table.json (for default: type the glyph itself)."
    try:
        table = json.loads((asset_dir()/'glyph_table.json').read_text())
        return {row[0] for rows in table.values() for row in rows}
    except Exception:
        return set()

def _skey(name, glyph, key, glyphs):
    if key in SP or _typable(key): return key
    if glyph in glyphs: return _typed(glyph)
    return ''

_map_cache, _map_mtime, _map_logged = {}, None, None

def name_map(db_path=None, force=False):
    "Map sound `name` (number) → key string to type, from the SQLite library."
    global _map_cache, _map_mtime, _map_logged
    path = Path(db_path) if db_path else data_dir()/'gnn.db'
    if not path.is_file():
        if _map_logged != 'missing':
            log.warning('no sound library at %s — assign numbers on the Sound Names page first', path)
            _map_logged = 'missing'
        _map_cache, _map_mtime = {}, None
        return {}
    try: mtime = path.stat().st_mtime
    except OSError: mtime = None
    if not force and _map_mtime == mtime and _map_cache is not None and _map_logged != 'missing':
        return _map_cache
    try:
        from fastlite import database
    except Exception as e:
        log.error('fastlite required to read the sound library: %s', e); return {}
    class Sound: id:int=None; name:str=''; glyph:str=''; key:str=''; samples:bytes=b''
    sounds = database(str(path)).create(Sound, pk='id')
    glyphs = _glyphs()
    out = {}
    for s in sounds():
        k = _skey(s.name, s.glyph or '', s.key or '', glyphs)
        if s.name and k: out[s.name.strip()] = k
    _map_cache, _map_mtime = out, mtime
    if _map_logged != len(out):
        log.info('loaded %d number→glyph mappings from %s', len(out), path)
        _map_logged = len(out)
    return out

_WORDS = dict(
    zero=0, oh=0, o=0, nought=0,
    one=1, two=2, three=3, four=4, five=5, six=6, seven=7, eight=8, nine=9,
    ten=10, eleven=11, twelve=12, thirteen=13, fourteen=14, fifteen=15,
    sixteen=16, seventeen=17, eighteen=18, nineteen=19,
    twenty=20, thirty=30, forty=40, fourty=40, fifty=50, sixty=60, seventy=70, eighty=80, ninety=90,
)

def digitize(text):
    "Turn spoken number words (and trailing punctuation) into digit tokens. Mirrors Swift NumeralTranscript."
    raw = (text or '').lower().replace('-', ' ').replace(',', ' ')
    parts = []
    for tok in raw.split():
        w = tok.strip('.,;:!?\'\"')
        if not w: continue
        if w.isdigit(): parts.append(w); continue
        if w in _WORDS: parts.append(str(_WORDS[w])); continue
        parts.append(w)
    # "one two three" → keep as separate digit tokens
    return parts

def resolve(text, mapping=None):
    "Turn a Transcribe numeral string into one or more keys to type."
    mapping = name_map() if mapping is None else mapping
    tokens = digitize(text)
    if not tokens: return []
    if not mapping:
        # Nothing configured yet — type the digits as-is so the link is still testable.
        return [' '.join(tokens)]
    keys, miss = [], []
    for tok in tokens:
        if tok in mapping: keys.append(mapping[tok])
        else: miss.append(tok)
    if miss: log.warning('no glyph for number(s) %s — assign them on Sound Names', ', '.join(miss))
    return keys


